// Append lead to CSV ledger
const fs = require('fs');
const b = $input.first().json.body || $input.first().json;
const row = [b.name || '', b.email || '', b.source || '', b.message || ''].map(v => String(v).replace(/"/g, '""'));
const line = `"${new Date().toISOString()}","${row.join('","')}"`;
const path = '$param:ledger_path';
if (!fs.existsSync(path)) fs.writeFileSync(path, 'received_at,name,email,source,message\n');
fs.appendFileSync(path, line + '\n');
return [{ json: { ok: true, logged: b.email || 'unknown', total_bytes: fs.statSync(path).size } }];
